function volDoD(d, n, mult){
    n=n||50; mult=mult||2;
    var o=[], i, j;
    if(!d||!d.length) return o;
    for(i=0;i<d.length;i++){
      var b=d[i];
      if(!b||b.time==null) continue;
      if(i<n){ o.push({time:b.time}); continue; }
      var r=rvolAt(d, i, n);
      if(r==null){ o.push({time:b.time}); continue; }
      var lo=1e99, hi=0, v;
      for(j=i-n;j<=i;j++){
        v=d[j]&&d[j].volume;
        if(!(typeof v==="number"&&isFinite(v)&&v>0)){ lo=0; break; }
        if(v<lo) lo=v;
        if(v>hi) hi=v;
      }
      // A 50-bar window wider than 80× is two volume units (Yahoo USD notional
      // vs the warehouse coin tape), not a capitulation. Leave a gap.
      if(!(lo>0) || hi/lo>=80){ o.push({time:b.time}); continue; }
      var prev=d[i-1];
      var range=b.high-b.low;
      var loc=range>0?(b.close-b.low)/range:0.5;
      var priorLo=1e99;
      for(j=i-n;j<i;j++) if(d[j].low<priorLo) priorLo=d[j].low;
      var atLow=b.low<=priorLo;
      var down=prev && b.close<prev.close;
      var tag="";
      if(r>=mult && atLow && loc<=0.35 && down) tag="CAPIT";
      else if(r>=mult && atLow && loc>=0.55) tag="STOP";
      else if(r>=mult) tag="OUT";
      o.push({time:b.time, value:r, loc:loc, tag:tag});
    }
    return o;
  }

